package com.slayercodex;

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Adds a "Slayer" toggle button to the bank UI. When toggled on, hides any bank widget
 * whose item id is not in {@link SlayerCodexTaskState#getRelevantItemIds()} for the
 * currently focused monster. Robust against script changes because it does not rebuild
 * the bank widgets — it only flips visibility of existing item children.
 */
@Slf4j
@Singleton
public class SlayerCodexBankFilter
{
	private static final int TOGGLE_X = 392;
	private static final int TOGGLE_Y = 6;
	private static final int TOGGLE_SIZE = 22;

	// Lower opacity = more visible. 0 = full color, 255 = invisible.
	private static final int OPACITY_ON = 0;
	private static final int OPACITY_OFF = 70;
	private static final int OPACITY_DISABLED = 140;

	// Standard OSRS bank slot grid
	private static final int ITEMS_PER_ROW = 8;
	private static final int ITEM_STRIDE_X = 48;
	private static final int ITEM_STRIDE_Y = 36;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final SlayerCodexTaskState taskState;
	private final SlayerCodexConfig config;

	private boolean filterActive;
	private Widget toggleWidget;
	private final IdentityHashMap<Widget, int[]> savedPositions = new IdentityHashMap<>();

	@Inject
	public SlayerCodexBankFilter(
		Client client,
		ClientThread clientThread,
		ItemManager itemManager,
		SlayerCodexTaskState taskState,
		SlayerCodexConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.taskState = taskState;
		this.config = config;
	}

	public void shutDown()
	{
		// If the filter is active while the bank is open, put the hidden/repacked
		// items back before the plugin goes away.
		if (filterActive)
		{
			clientThread.invoke(this::unhideAllItems);
		}
		filterActive = false;
		toggleWidget = null;
	}

	public boolean isFilterActive()
	{
		return filterActive;
	}

	public void setFilterActive(boolean active)
	{
		if (filterActive == active)
		{
			return;
		}
		filterActive = active;
		clientThread.invoke(() ->
		{
			refreshToggleAppearance();
			if (filterActive)
			{
				applyFilter();
			}
			else
			{
				unhideAllItems();
			}
		});
	}

	public void onTaskStateChanged()
	{
		clientThread.invoke(() ->
		{
			if (!taskState.hasFocus() && filterActive)
			{
				filterActive = false;
				unhideAllItems();
			}
			refreshToggleAppearance();
			if (filterActive)
			{
				applyFilter();
			}
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.BANKMAIN)
		{
			return;
		}

		if (!config.bankFilterEnabled())
		{
			return;
		}

		// Bank widgets are re-created on each open — the previous reference is stale.
		toggleWidget = null;

		if (config.autoApplyBankFilter() && taskState.hasFocus())
		{
			filterActive = true;
		}

		clientThread.invoke(this::injectToggleWidget);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
		{
			return;
		}

		refreshToggleAppearance();

		if (filterActive)
		{
			applyFilter();
		}
	}

	private void injectToggleWidget()
	{
		try
		{
			Widget parent = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
			if (parent == null)
			{
				return;
			}

			Widget child = parent.createChild(-1, WidgetType.GRAPHIC);
			child.setName("Slayer Codex Filter");
			child.setItemId(ItemID.SLAYER_HELMET_I);
			child.setItemQuantity(0);
			child.setItemQuantityMode(0);
			child.setOriginalX(TOGGLE_X);
			child.setOriginalY(TOGGLE_Y);
			child.setOriginalWidth(TOGGLE_SIZE);
			child.setOriginalHeight(TOGGLE_SIZE);
			child.setHasListener(true);
			child.setNoClickThrough(true);
			child.setAction(0, "Toggle Slayer filter");
			child.setOnOpListener((JavaScriptCallback) ev -> handleToggle());
			child.revalidate();

			toggleWidget = child;
			refreshToggleAppearance();
		}
		catch (Throwable ex)
		{
			log.debug("Could not inject Slayer Codex bank toggle", ex);
		}
	}

	private void handleToggle()
	{
		if (!taskState.hasFocus())
		{
			filterActive = false;
			refreshToggleAppearance();
			return;
		}

		filterActive = !filterActive;
		refreshToggleAppearance();
		if (filterActive)
		{
			applyFilter();
		}
		else
		{
			unhideAllItems();
		}
	}

	private void refreshToggleAppearance()
	{
		Widget widget = toggleWidget;
		if (widget == null)
		{
			return;
		}

		try
		{
			boolean canActivate = taskState.hasFocus();
			int opacity;
			String tooltip;
			if (!canActivate)
			{
				opacity = OPACITY_DISABLED;
				tooltip = "Slayer Codex: detect or pick a Slayer task to enable";
			}
			else if (filterActive)
			{
				opacity = OPACITY_ON;
				tooltip = "Slayer Codex filter ON — showing only items for " + taskState.getMonsterName();
			}
			else
			{
				opacity = OPACITY_OFF;
				tooltip = "Slayer Codex filter OFF — click to show only items for " + taskState.getMonsterName();
			}

			widget.setOpacity(opacity);
			widget.setAction(0, tooltip);
		}
		catch (Throwable ignored)
		{
		}
	}

	private void applyFilter()
	{
		try
		{
			Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
			if (container == null)
			{
				return;
			}

			java.util.Set<Integer> allowed = taskState.getRelevantItemIds();
			if (allowed.isEmpty())
			{
				return;
			}

			Widget[] children = container.getDynamicChildren();
			if (children == null)
			{
				return;
			}

			savedPositions.clear();

			List<Widget> kept = new ArrayList<>();
			int leftmostX = Integer.MAX_VALUE;
			int topmostY = Integer.MAX_VALUE;

			for (Widget child : children)
			{
				if (child == null)
				{
					continue;
				}

				int rawId = child.getItemId();
				if (rawId <= 0)
				{
					// Tab dividers / separators — hide while filter is on so kept items pack cleanly.
					savedPositions.put(child, new int[]{child.getOriginalX(), child.getOriginalY()});
					child.setHidden(true);
					continue;
				}

				savedPositions.put(child, new int[]{child.getOriginalX(), child.getOriginalY()});
				leftmostX = Math.min(leftmostX, child.getOriginalX());
				topmostY = Math.min(topmostY, child.getOriginalY());

				int canonicalId = itemManager.canonicalize(rawId);
				boolean keep = allowed.contains(canonicalId) || allowed.contains(rawId);
				if (keep)
				{
					kept.add(child);
					child.setHidden(false);
				}
				else
				{
					child.setHidden(true);
				}
			}

			if (kept.isEmpty() || leftmostX == Integer.MAX_VALUE)
			{
				return;
			}

			// Repack kept items into a contiguous grid anchored at the bank's top-left.
			for (int i = 0; i < kept.size(); i++)
			{
				Widget item = kept.get(i);
				int row = i / ITEMS_PER_ROW;
				int col = i % ITEMS_PER_ROW;
				item.setOriginalX(leftmostX + col * ITEM_STRIDE_X);
				item.setOriginalY(topmostY + row * ITEM_STRIDE_Y);
				item.revalidate();
			}
		}
		catch (Throwable ex)
		{
			log.debug("Slayer Codex bank filter render failed", ex);
		}
	}

	private void unhideAllItems()
	{
		try
		{
			Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
			if (container == null)
			{
				savedPositions.clear();
				return;
			}

			// Restore original positions for any widget we moved or hid.
			for (Map.Entry<Widget, int[]> entry : savedPositions.entrySet())
			{
				Widget w = entry.getKey();
				int[] xy = entry.getValue();
				try
				{
					w.setOriginalX(xy[0]);
					w.setOriginalY(xy[1]);
					w.setHidden(false);
					w.revalidate();
				}
				catch (Throwable ignored)
				{
				}
			}
			savedPositions.clear();

			// Catch any children that weren't tracked (e.g. added after filter applied).
			Widget[] children = container.getDynamicChildren();
			if (children == null)
			{
				return;
			}
			for (Widget child : children)
			{
				if (child == null || child.getItemId() <= 0)
				{
					continue;
				}
				child.setHidden(false);
			}
		}
		catch (Throwable ex)
		{
			log.debug("Slayer Codex bank unhide failed", ex);
		}
	}
}

package com.slayercodex;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("slayercodex")
public interface SlayerCodexConfig extends Config
{
	@ConfigSection(
		name = "Task Detection",
		description = "Settings related to Slayer task auto-detection",
		position = 0
	)
	String taskSection = "task";

	@ConfigSection(
		name = "Display",
		description = "What to show in the panel",
		position = 1
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Recommendations",
		description = "How gear recommendations are determined",
		position = 2
	)
	String recommendSection = "recommend";

	@ConfigSection(
		name = "Bank",
		description = "Filter your bank to show only items relevant to your current Slayer task",
		position = 3
	)
	String bankSection = "bank";

	// ── Task Detection ─────────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "autoDetectTask",
		name = "Auto-detect Slayer task",
		description = "Automatically switch to the matching strategy when a Slayer assignment is detected in chat.",
		section = taskSection,
		position = 0
	)
	default boolean autoDetectTask()
	{
		return true;
	}

	@ConfigItem(
		keyName = "preferBossVariant",
		name = "Prefer boss variant",
		description = "When a task has a boss variant (e.g. Hellhounds → Cerberus), auto-select the boss page instead.",
		section = taskSection,
		position = 1
	)
	default boolean preferBossVariant()
	{
		return true;
	}

	// ── Display ────────────────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "showTaskCountdown",
		name = "Show task remaining count",
		description = "Show how many kills are left when a task is detected.",
		section = displaySection,
		position = 0
	)
	default boolean showTaskCountdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "compactGearTable",
		name = "Compact gear table rows",
		description = "Reduces the row height in the gear table so more slots are visible without scrolling.",
		section = displaySection,
		position = 1
	)
	default boolean compactGearTable()
	{
		return false;
	}

	// ── Recommendations ────────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "defaultCombatStyle",
		name = "Preferred combat style",
		description = "Which style tab to auto-select first when opening a monster (Auto = first available).",
		section = recommendSection,
		position = 0
	)
	default StylePreference defaultCombatStyle()
	{
		return StylePreference.AUTO;
	}

	@ConfigItem(
		keyName = "highlightOwnedItems",
		name = "Highlight owned items in panel",
		description = "Color items in the Your Best column based on whether they are equipped, in your inventory, or in your bank.",
		section = recommendSection,
		position = 1
	)
	default boolean highlightOwnedItems()
	{
		return true;
	}

	// ── Bank & In-game ─────────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "bankFilterEnabled",
		name = "Show bank filter button",
		description = "Adds a 'Slayer' toggle to the bank UI that hides items not relevant to your current task.",
		section = bankSection,
		position = 0
	)
	default boolean bankFilterEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoApplyBankFilter",
		name = "Auto-filter on bank open",
		description = "Automatically activate the bank filter when you open the bank with a task focused. Toggle off any time via the bank button.",
		section = bankSection,
		position = 1
	)
	default boolean autoApplyBankFilter()
	{
		return false;
	}

	enum StylePreference
	{
		AUTO, MELEE, RANGED, MAGIC
	}
}

package com.slayercodex;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.zip.GZIPInputStream;
import javax.inject.Singleton;

@Singleton
public class SlayerCodexDataStore
{
	private List<MonsterSummary> monsterSummaries = Collections.emptyList();
	private Map<String, String> taskNameToMonsterKey = Collections.emptyMap();
	private Map<String, String> baseTaskToBossKey = Collections.emptyMap();
	// Fully parsed at load so the multi-megabyte Gson DOM can be garbage collected
	// instead of living in the client's heap for the whole session.
	private Map<String, MonsterDetails> detailsByKey = Collections.emptyMap();
	private String crawlDate = "unknown";

	/**
	 * Task names whose strategy lives under a differently-named page. Only for cases where the
	 * dataset entry is genuinely killable on that task — never a "close enough" guess. Keys are
	 * normalized task names (lowercase, alphanumerics only).
	 */
	private static final Map<String, String> TASK_ALIASES = buildTaskAliases();

	private static Map<String, String> buildTaskAliases()
	{
		Map<String, String> aliases = new LinkedHashMap<>();
		// Basilisk Knights are assigned under, and killable on, the Basilisks task.
		aliases.put("basilisk", "basilisk_knight");
		// Shellbane gryphons are the Varlamore gryphon assigned on the Gryphons task.
		aliases.put("gryphon", "shellbane_gryphon");
		return Collections.unmodifiableMap(aliases);
	}

	public void load() throws IOException
	{
		JsonObject root;
		try (InputStream in = SlayerCodexDataStore.class.getResourceAsStream("/monster_strategies.json.gz"))
		{
			if (in == null)
			{
				throw new IOException("Resource not found: /monster_strategies.json.gz");
			}

			// RuneLite bundles a pre-2.8.6 Gson — the non-deprecated static
			// JsonParser.parseReader does not exist there.
			root = new JsonParser()
				.parse(new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8))
				.getAsJsonObject();
		}

		JsonObject monsters = root.getAsJsonObject("monsters");
		monsterSummaries = buildSummaries(monsters);
		taskNameToMonsterKey = buildTaskLookup(monsterSummaries);
		baseTaskToBossKey = buildBossLookup(root, monsterSummaries);
		crawlDate = readCrawlDate(root);

		Map<String, MonsterDetails> details = new LinkedHashMap<>();
		if (monsters != null)
		{
			for (Map.Entry<String, JsonElement> entry : monsters.entrySet())
			{
				if (!entry.getValue().isJsonObject())
				{
					continue;
				}
				MonsterDetails parsed = parseMonsterDetails(entry.getKey(), entry.getValue().getAsJsonObject());
				if (parsed != null)
				{
					details.put(entry.getKey(), parsed);
				}
			}
		}
		detailsByKey = Collections.unmodifiableMap(details);

	}

	public int getMonsterCount()
	{
		return monsterSummaries.size();
	}

	public String getCrawlDate()
	{
		return crawlDate;
	}

	private static String readCrawlDate(JsonObject root)
	{
		JsonObject meta = getObject(root, "_meta");
		String date = getString(meta, "crawl_date");
		return date == null ? "unknown" : date;
	}

	public List<MonsterSummary> getMonsterSummaries()
	{
		return Collections.unmodifiableList(monsterSummaries);
	}

	/**
	 * Returns the boss variant key for a base task key, or null if none exists.
	 * e.g. "gargoyles" -> "grotesque_guardians"
	 */
	public String getBossKeyForBase(String baseKey)
	{
		if (baseKey == null)
		{
			return null;
		}
		// baseTaskToBossKey is keyed by normalized task name; monster keys are snake_case.
		String normalizedBase = normalize(baseKey.replace('_', ' '));
		return firstPresentKey(
			baseTaskToBossKey.get(normalizedBase),
			baseTaskToBossKey.get(toSingular(normalizedBase)));
	}

	public MonsterDetails getMonsterDetails(String key)
	{
		return key == null ? null : detailsByKey.get(key);
	}

	/**
	 * Every gear item name (and alt name) referenced anywhere in the bundled dataset.
	 * Lets {@link SlayerCodexItemResolver} index only the items this plugin can ever ask
	 * about instead of every item in the game.
	 */
	public Set<String> getAllGearItemNames()
	{
		Set<String> names = new LinkedHashSet<>();
		for (MonsterDetails details : detailsByKey.values())
		{
			for (CombatStyleDetails style : details.getCombatStyles())
			{
				for (List<GearRow> rows : style.getTierRows().values())
				{
					for (GearRow row : rows)
					{
						if (row.getItemName() != null && !row.getItemName().isEmpty())
						{
							names.add(row.getItemName());
						}
						if (row.getAltName() != null && !row.getAltName().isEmpty())
						{
							names.add(row.getAltName());
						}
					}
				}
			}
		}
		return Collections.unmodifiableSet(names);
	}

	private MonsterDetails parseMonsterDetails(String key, JsonObject monster)
	{
		MonsterSummary summary = createSummary(key, monster);
		JsonObject meta = getObject(monster, "meta");

		Map<String, String> footnotes = new LinkedHashMap<>();
		readLegacyFootnotes(monster, footnotes);

		List<CombatStyleDetails> styles = new ArrayList<>();
		JsonArray builds = getArray(monster, "builds");
		if (builds != null && builds.size() > 0)
		{
			for (JsonElement buildElement : builds)
			{
				if (!buildElement.isJsonObject())
				{
					continue;
				}

				JsonObject build = buildElement.getAsJsonObject();
				String styleName = firstNonBlank(
					getString(build, "label"),
					getString(build, "style"),
					getString(build, "id"),
					"Setup");

				String noteNamespace = "build:" + normalize(styleName);
				BuildNoteIndex noteIndex = buildBuildNoteIndex(build, noteNamespace, footnotes);
				Map<Integer, List<GearRow>> tierRows = parseBuildTierRows(build, noteIndex);

				styles.add(new CombatStyleDetails(
					styleName,
					Collections.unmodifiableMap(tierRows),
					noteIndex.getBuildNoteIds()));
			}
		}

		if (styles.isEmpty())
		{
			JsonObject gear = getObject(monster, "gear");
			if (gear != null)
			{
				for (String styleName : summary.getCombatStyles())
				{
					JsonObject styleObject = getObject(gear, styleName);
					if (styleObject == null)
					{
						continue;
					}

					Map<Integer, List<GearRow>> tierToRows = new HashMap<>();
					for (Map.Entry<String, JsonElement> slotEntry : styleObject.entrySet())
					{
						String slot = slotEntry.getKey();
						JsonArray itemArray = getArray(styleObject, slot);
						if (itemArray == null)
						{
							continue;
						}

						for (JsonElement itemElement : itemArray)
						{
							if (!itemElement.isJsonObject())
							{
								continue;
							}

							JsonObject item = itemElement.getAsJsonObject();
							int tier = getInt(item, "tier", 1);
							String itemName = getString(item, "name");
							if (itemName == null)
							{
								continue;
							}

							String altName = getString(item, "alt_name");
							List<String> noteIds = getStringArray(item, "notes");

							GearRow row = new GearRow(
								normalizeSlot(slot),
								itemName,
								altName == null ? "" : altName,
								noteIds
							);

							tierToRows.computeIfAbsent(tier, ignored -> new ArrayList<>()).add(row);
						}
					}

					styles.add(new CombatStyleDetails(
						styleName,
						Collections.unmodifiableMap(sortAndFreezeTierRows(tierToRows)),
						Collections.emptyList()));
				}
			}
		}

		styles.sort(Comparator.comparing(CombatStyleDetails::getName));

		return new MonsterDetails(
			summary,
			Collections.unmodifiableList(styles),
			Collections.unmodifiableMap(footnotes),
			getString(meta, "base_task"),
			getBoolean(meta, "is_boss_variant", false),
			getBoolean(meta, "requires_slayer_task", false)
		);
	}

	private void readLegacyFootnotes(JsonObject monster, Map<String, String> footnotes)
	{
		JsonObject notesObject = getObject(monster, "notes");
		if (notesObject == null)
		{
			return;
		}

		List<String> noteIds = new ArrayList<>();
		for (Map.Entry<String, JsonElement> entry : notesObject.entrySet())
		{
			if (entry.getValue().isJsonPrimitive())
			{
				noteIds.add(entry.getKey());
			}
		}
		noteIds.sort(String::compareTo);

		for (String noteId : noteIds)
		{
			String text = getString(notesObject, noteId);
			if (text != null && !text.trim().isEmpty())
			{
				footnotes.put(noteId, text);
			}
		}
	}

	private BuildNoteIndex buildBuildNoteIndex(JsonObject build, String namespace, Map<String, String> footnotes)
	{
		BuildNoteIndex index = new BuildNoteIndex();
		JsonObject notesObject = getObject(build, "notes");
		if (notesObject == null)
		{
			return index;
		}

		JsonArray buildNotes = getArray(notesObject, "build_notes");
		if (buildNotes != null)
		{
			int noteCounter = 1;
			for (JsonElement noteElement : buildNotes)
			{
				if (noteElement.isJsonNull())
				{
					continue;
				}

				String text = noteElement.getAsString();
				if (text == null || text.trim().isEmpty())
				{
					continue;
				}

				String noteId = namespace + ":build:" + noteCounter++;
				footnotes.put(noteId, text);
				index.addBuildNoteId(noteId);
			}
		}

		JsonArray itemOrSlotNotes = getArray(notesObject, "by_item_or_slot");
		if (itemOrSlotNotes != null)
		{
			int generated = 1;
			for (JsonElement noteElement : itemOrSlotNotes)
			{
				if (!noteElement.isJsonObject())
				{
					continue;
				}

				JsonObject noteObject = noteElement.getAsJsonObject();
				String noteText = getString(noteObject, "note_text");
				if (noteText == null || noteText.trim().isEmpty())
				{
					continue;
				}

				String rawId = firstNonBlank(getString(noteObject, "note_id"), "n" + generated++);
				String noteId = namespace + ":" + rawId;
				footnotes.put(noteId, noteText);
				index.addTargetNote(
					getString(noteObject, "target_type"),
					getString(noteObject, "target_key"),
					noteId);
			}
		}

		return index;
	}

	private Map<Integer, List<GearRow>> parseBuildTierRows(JsonObject build, BuildNoteIndex noteIndex)
	{
		Map<Integer, List<GearRow>> tierToRows = new HashMap<>();
		JsonObject gearObject = getObject(build, "gear");
		JsonObject bySlot = getObject(gearObject, "by_slot");
		if (bySlot == null)
		{
			return Collections.emptyMap();
		}

		for (Map.Entry<String, JsonElement> slotEntry : bySlot.entrySet())
		{
			String slot = normalizeSlot(slotEntry.getKey());
			JsonArray itemArray = getArray(bySlot, slotEntry.getKey());
			if (itemArray == null)
			{
				continue;
			}

			for (JsonElement itemElement : itemArray)
			{
				if (!itemElement.isJsonObject())
				{
					continue;
				}

				JsonObject item = itemElement.getAsJsonObject();
				String itemName = getString(item, "name");
				if (itemName == null || itemName.trim().isEmpty())
				{
					continue;
				}

				int tier = getInt(item, "tier", 1);
				String altName = getString(item, "alt_name");

				List<String> noteIds = new ArrayList<>();
				noteIds.addAll(noteIndex.getNotesForSlot(slot));
				noteIds.addAll(noteIndex.getNotesForItem(itemName));
				if (altName != null && !altName.trim().isEmpty())
				{
					noteIds.addAll(noteIndex.getNotesForItem(altName));
				}

				for (String noteRef : getStringArray(item, "notes_refs"))
				{
					String resolved = noteIndex.resolveByRawRef(noteRef);
					noteIds.add(resolved == null ? noteRef : resolved);
				}

				List<String> uniqueNoteIds = dedupeInOrder(noteIds);

				GearRow row = new GearRow(
					slot,
					itemName,
					altName == null ? "" : altName,
					uniqueNoteIds);

				tierToRows.computeIfAbsent(tier, ignored -> new ArrayList<>()).add(row);
			}
		}

		return sortAndFreezeTierRows(tierToRows);
	}

	private Map<Integer, List<GearRow>> sortAndFreezeTierRows(Map<Integer, List<GearRow>> tierToRows)
	{
		Map<Integer, List<GearRow>> sortedTierRows = new LinkedHashMap<>();
		List<Integer> tiers = new ArrayList<>(tierToRows.keySet());
		tiers.sort(Integer::compareTo);
		for (Integer tier : tiers)
		{
			List<GearRow> rows = tierToRows.get(tier);
			rows.sort(Comparator.comparing(GearRow::getSlot).thenComparing(GearRow::getItemName));
			sortedTierRows.put(tier, Collections.unmodifiableList(rows));
		}
		return sortedTierRows;
	}

	/**
	 * Resolves a Slayer task name (as reported by the game's own slayer DB tables) to a
	 * monster key in the bundled dataset, or null when nothing sensible matches.
	 *
	 * <p>Matching is deliberately strict — exact normalized name/key, then a naive plural
	 * fold, then an explicit alias table. An earlier revision also indexed the last word of
	 * every multi-word name and fell back to bidirectional substring matching; both produced
	 * only false positives against the real task list (a "Hydras" task resolved to Alchemical
	 * Hydra, "Rats" to Barbarian Assault), so returning null and letting the panel show its
	 * "no strategy bundled" state is strictly better than guessing.
	 */
	public String findBestMonsterKeyForTask(String taskName, boolean preferBossVariant)
	{
		if (taskName == null || taskName.trim().isEmpty())
		{
			return null;
		}

		String normalized = normalize(taskName);
		String singularNormalized = toSingular(normalized);

		String key = firstPresentKey(
			taskNameToMonsterKey.get(normalized),
			taskNameToMonsterKey.get(singularNormalized),
			TASK_ALIASES.get(normalized),
			TASK_ALIASES.get(singularNormalized));

		// Boss variants are keyed by task name, not by base monster key: most base monsters
		// (cave kraken, kalphites, hellhounds...) have no strategy page of their own, so a
		// lookup that required the base to exist in the dataset would never fire.
		String bossKey = firstPresentKey(
			baseTaskToBossKey.get(normalized),
			baseTaskToBossKey.get(singularNormalized));

		if (bossKey != null && (preferBossVariant || key == null))
		{
			// Either the player asked for boss variants, or we have no base strategy at all
			// and the boss is killable on this task — showing it beats showing nothing.
			return bossKey;
		}

		return key;
	}

	/**
	 * Returns the first candidate that names a monster actually present in the dataset.
	 * Guards every lookup path against stale keys in the crawler output.
	 */
	private String firstPresentKey(String... candidates)
	{
		for (String candidate : candidates)
		{
			if (candidate != null && detailsByKey.containsKey(candidate))
			{
				return candidate;
			}
		}
		return null;
	}

	private List<MonsterSummary> buildSummaries(JsonObject monstersObject)
	{
		if (monstersObject == null)
		{
			return Collections.emptyList();
		}

		List<MonsterSummary> summaries = new ArrayList<>();
		for (Map.Entry<String, JsonElement> entry : monstersObject.entrySet())
		{
			if (!entry.getValue().isJsonObject())
			{
				continue;
			}

			MonsterSummary summary = createSummary(entry.getKey(), entry.getValue().getAsJsonObject());
			if (summary != null)
			{
				summaries.add(summary);
			}
		}

		summaries.sort(Comparator.comparing(MonsterSummary::getName, String.CASE_INSENSITIVE_ORDER));
		return summaries;
	}

	private Map<String, String> buildTaskLookup(List<MonsterSummary> summaries)
	{
		Map<String, String> lookup = new LinkedHashMap<>();
		for (MonsterSummary summary : summaries)
		{
			String key = summary.getKey();
			String normalizedName = normalize(summary.getName());
			String normalizedKey = normalize(key.replace('_', ' '));

			lookup.putIfAbsent(normalizedName, key);
			lookup.putIfAbsent(toSingular(normalizedName), key);
			lookup.putIfAbsent(normalizedKey, key);
			lookup.putIfAbsent(toSingular(normalizedKey), key);
		}
		return Collections.unmodifiableMap(lookup);
	}

	/**
	 * Builds task-name → boss-monster-key. Keyed by the normalized base *task* name so it
	 * resolves straight off the assignment, and tolerant of crawler key drift on the boss
	 * side (the dataset has shipped e.g. "vet_ion" where the monster key is "vetion").
	 */
	private Map<String, String> buildBossLookup(JsonObject rootObject, List<MonsterSummary> summaries)
	{
		JsonObject bossVariants = getObject(rootObject, "boss_variants");
		if (bossVariants == null)
		{
			return Collections.emptyMap();
		}

		Map<String, String> keysByNormalized = new LinkedHashMap<>();
		for (MonsterSummary summary : summaries)
		{
			keysByNormalized.putIfAbsent(normalize(summary.getKey()), summary.getKey());
		}

		Map<String, String> lookup = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : bossVariants.entrySet())
		{
			if (!entry.getValue().isJsonObject())
			{
				continue;
			}

			String boss = getString(entry.getValue().getAsJsonObject(), "boss");
			if (boss == null)
			{
				continue;
			}

			String bossKey = keysByNormalized.get(normalize(boss));
			if (bossKey == null)
			{
				continue;
			}

			String normalizedBase = normalize(entry.getKey().replace('_', ' '));
			lookup.putIfAbsent(normalizedBase, bossKey);
			lookup.putIfAbsent(toSingular(normalizedBase), bossKey);
		}

		return Collections.unmodifiableMap(lookup);
	}

	private static String normalize(String input)
	{
		String lowered = input.toLowerCase();
		StringBuilder builder = new StringBuilder(lowered.length());
		for (int i = 0; i < lowered.length(); i++)
		{
			char ch = lowered.charAt(i);
			if (Character.isLetterOrDigit(ch))
			{
				builder.append(ch);
			}
		}
		return builder.toString();
	}

	private static String toSingular(String value)
	{
		if (value.endsWith("ies") && value.length() > 3)
		{
			return value.substring(0, value.length() - 3) + "y";
		}
		if (value.endsWith("ses") && value.length() > 3)
		{
			return value.substring(0, value.length() - 2);
		}
		if (value.endsWith("s") && value.length() > 1)
		{
			return value.substring(0, value.length() - 1);
		}
		return value;
	}

	private MonsterSummary createSummary(String key, JsonObject monster)
	{
		if (monster == null)
		{
			return null;
		}

		String name = getString(monster, "name");
		if (name == null)
		{
			name = key;
		}

		JsonObject meta = getObject(monster, "meta");

		List<String> combatStyles = getStringArray(monster, "combat_styles");
		if (combatStyles.isEmpty())
		{
			combatStyles = getBuildStyleNames(monster);
		}

		return new MonsterSummary(
			key,
			name,
			getString(monster, "wiki_page"),
			getIntOrNull(meta, "slayer_level"),
			getIntOrNull(meta, "combat_level"),
			getIntOrNull(meta, "task_weight"),
			Collections.unmodifiableList(combatStyles)
		);
	}

	private List<String> getBuildStyleNames(JsonObject monster)
	{
		JsonArray builds = getArray(monster, "builds");
		if (builds == null)
		{
			return Collections.emptyList();
		}

		List<String> names = new ArrayList<>();
		for (JsonElement buildElement : builds)
		{
			if (!buildElement.isJsonObject())
			{
				continue;
			}

			JsonObject build = buildElement.getAsJsonObject();
			String styleName = firstNonBlank(
				getString(build, "label"),
				getString(build, "style"),
				getString(build, "id"));
			if (styleName != null)
			{
				names.add(styleName);
			}
		}
		return names;
	}

	private static String normalizeSlot(String slot)
	{
		if (slot == null)
		{
			return "";
		}
		return slot.trim().toUpperCase();
	}

	private static String firstNonBlank(String... values)
	{
		for (String value : values)
		{
			if (value != null && !value.trim().isEmpty())
			{
				return value.trim();
			}
		}
		return null;
	}

	private static List<String> dedupeInOrder(List<String> values)
	{
		LinkedHashMap<String, Boolean> seen = new LinkedHashMap<>();
		for (String value : values)
		{
			if (value == null || value.trim().isEmpty())
			{
				continue;
			}
			seen.putIfAbsent(value, Boolean.TRUE);
		}
		return new ArrayList<>(seen.keySet());
	}

	private static JsonObject getObject(JsonObject object, String key)
	{
		if (object == null || !object.has(key) || !object.get(key).isJsonObject())
		{
			return null;
		}
		return object.getAsJsonObject(key);
	}

	private static JsonArray getArray(JsonObject object, String key)
	{
		if (object == null || !object.has(key) || !object.get(key).isJsonArray())
		{
			return null;
		}
		return object.getAsJsonArray(key);
	}

	private static String getString(JsonObject object, String key)
	{
		if (object == null || !object.has(key) || object.get(key).isJsonNull())
		{
			return null;
		}
		return object.get(key).getAsString();
	}

	private static List<String> getStringArray(JsonObject object, String key)
	{
		JsonArray array = getArray(object, key);
		if (array == null)
		{
			return Collections.emptyList();
		}

		List<String> result = new ArrayList<>();
		for (JsonElement element : array)
		{
			if (!element.isJsonNull())
			{
				result.add(element.getAsString());
			}
		}
		return result;
	}

	private static Integer getIntOrNull(JsonObject object, String key)
	{
		if (object == null || !object.has(key) || object.get(key).isJsonNull())
		{
			return null;
		}
		return object.get(key).getAsInt();
	}

	private static int getInt(JsonObject object, String key, int fallback)
	{
		Integer value = getIntOrNull(object, key);
		return value == null ? fallback : value;
	}

	private static boolean getBoolean(JsonObject object, String key, boolean fallback)
	{
		if (object == null || !object.has(key) || object.get(key).isJsonNull())
		{
			return fallback;
		}
		return object.get(key).getAsBoolean();
	}

