	{
		if (monsterKey == null)
		{
			return false;
		}

		SlayerCodexDataStore.MonsterSummary summary = summaryByKey.get(monsterKey);
		if (summary == null)
		{
			return false;
		}

		if (!searchField.getText().isEmpty())
		{
