	// Package-private and static so the chat-parsing logic is unit-testable.
	static TaskUpdate parseTaskUpdate(String message)
	{
		Matcher assignment = ASSIGNMENT_PATTERN.matcher(message);
		if (assignment.find())
		{
			int amount = Integer.parseInt(assignment.group(1));
			String task = cleanupTaskName(assignment.group(2));
			return new TaskUpdate(task, amount);
		}

		Matcher remaining = REMAINING_PATTERN.matcher(message);
		if (remaining.find())
		{
			String task = cleanupTaskName(remaining.group(1));
			int amount = Integer.parseInt(remaining.group(2));
			return new TaskUpdate(task, amount);
		}

		if (message.toLowerCase().contains("new slayer assignment"))
		{
			int colon = message.indexOf(':');
			if (colon >= 0 && colon < message.length() - 1)
			{
				String trailing = message.substring(colon + 1).trim();
				String[] chunks = trailing.split("\\(");
				String task = cleanupTaskName(chunks[0]);
				Integer amount = extractFirstNumber(trailing);
				if (task != null)
				{
					return new TaskUpdate(task, amount);
				}
			}
		}

		return null;
	}

	static String cleanupTaskName(String task)
	{
		if (task == null)
		{
			return null;
		}

		String cleaned = task
			.replace(".", "")
			.replace(";", "")
			.trim();

		String lower = cleaned.toLowerCase();
		int inIndex = lower.indexOf(" in ");
		int atIndex = lower.indexOf(" at ");
		int withIndex = lower.indexOf(" with ");
		int cutIndex = -1;
		for (int index : new int[] {inIndex, atIndex, withIndex})
		{
			if (index >= 0 && (cutIndex == -1 || index < cutIndex))
			{
				cutIndex = index;
			}
		}
		if (cutIndex >= 0)
		{
			cleaned = cleaned.substring(0, cutIndex).trim();
		}

		if (cleaned.isEmpty())
		{
			return null;
		}

		String[] pieces = cleaned.split("\\s+");
		StringBuilder title = new StringBuilder();
		for (String piece : pieces)
		{
			if (piece.isEmpty())
			{
				continue;
			}
			title.append(Character.toUpperCase(piece.charAt(0)));
			if (piece.length() > 1)
			{
				title.append(piece.substring(1).toLowerCase());
			}
			title.append(' ');
		}
		return title.toString().trim();
	}

	private static Integer extractFirstNumber(String text)
	{
		Matcher matcher = NUMBER_PATTERN.matcher(text);
		if (matcher.find())
		{
			return Integer.parseInt(matcher.group(1));
		}
		return null;
	}

	static final class TaskUpdate
	{
		final String taskName;
		final Integer remaining;

		private TaskUpdate(String taskName, Integer remaining)
		{
			this.taskName = taskName;
			this.remaining = remaining;
		}
	}
}

package com.slayercodex;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class SlayerCodexRecommendationService
{
	private static final Map<String, Integer> SLOT_ORDER = buildSlotOrder();

	private final SlayerCodexItemResolver itemResolver;
	private final SlayerCodexOwnershipTracker ownershipTracker;

	@Inject
	public SlayerCodexRecommendationService(
		SlayerCodexItemResolver itemResolver,
		SlayerCodexOwnershipTracker ownershipTracker)
	{
		this.itemResolver = itemResolver;
		this.ownershipTracker = ownershipTracker;
	}

	public List<RecommendationRow> buildRows(
		String monsterKey,
		SlayerCodexDataStore.CombatStyleDetails style)
	{
		if (style == null)
		{
			return Collections.emptyList();
		}

		Map<String, SlotAccumulator> slotMap = new LinkedHashMap<>();
		List<Integer> orderedTiers = new ArrayList<>(style.getTierRows().keySet());
		orderedTiers.sort(Integer::compareTo);

		for (Integer tier : orderedTiers)
		{
			for (SlayerCodexDataStore.GearRow row : style.getTierRows().getOrDefault(tier, Collections.emptyList()))
			{
				slotMap.computeIfAbsent(row.getSlot(), ignored -> new SlotAccumulator())
					.rowsByTier.putIfAbsent(tier, row);
			}
		}

		List<String> orderedSlots = new ArrayList<>(slotMap.keySet());
		orderedSlots.sort(this::compareSlot);

		List<RecommendationRow> rows = new ArrayList<>();
		for (String slot : orderedSlots)
		{
			SlotAccumulator acc = slotMap.get(slot);
			RecommendationCell wiki = buildWikiCell(acc);
			RecommendationCell bestOwned = buildBestOwnedCell(acc);
			rows.add(new RecommendationRow(slot, wiki, bestOwned, acc.collectNotes()));
		}
		return rows;
	}

	public String buildBestSetupStatus()
	{
		return ownershipTracker.isBankKnown()
			? "Your Best uses equipped, inventory and every bank item seen this session."
			: "Your Best uses equipped and inventory items until you open the bank once this session.";
	}

	/**
	 * Collects every resolvable item ID across every build/style/tier/slot for a monster.
	 * Used by the bank filter and item overlay to know which items belong to a task.
	 */
	public Set<Integer> collectAllRelevantItemIds(SlayerCodexDataStore.MonsterDetails details)
	{
		if (details == null)
		{
			return Collections.emptySet();
		}

		LinkedHashSet<Integer> ids = new LinkedHashSet<>();
		for (SlayerCodexDataStore.CombatStyleDetails style : details.getCombatStyles())
		{
			if (style == null)
			{
				continue;
			}
			for (List<SlayerCodexDataStore.GearRow> tierRows : style.getTierRows().values())
			{
				if (tierRows == null)
				{
					continue;
				}
				for (SlayerCodexDataStore.GearRow row : tierRows)
				{
					if (row == null)
					{
						continue;
					}
					ids.addAll(itemResolver.resolveItemIds(row.getItemName(), row.getAltName()));
				}
			}
		}
		return ids.isEmpty() ? Collections.emptySet() : Collections.unmodifiableSet(ids);
	}

	private RecommendationCell buildWikiCell(SlotAccumulator acc)
	{
		SlayerCodexDataStore.GearRow row = acc.rowsByTier.values().stream().findFirst().orElse(null);
		if (row == null)
		{
			return RecommendationCell.placeholder("-");
		}
		return buildCell(row, false);
	}

	private RecommendationCell buildBestOwnedCell(SlotAccumulator acc)
	{
		for (SlayerCodexDataStore.GearRow row : acc.rowsByTier.values())
		{
			RecommendationCell candidate = buildCell(row, true);
			if (candidate.isOwned())
			{
				return candidate;
			}
		}

		SlayerCodexDataStore.GearRow fallback = acc.rowsByTier.values().stream().findFirst().orElse(null);
		if (fallback == null)
		{
			return RecommendationCell.placeholder("No matching gear");
		}

		RecommendationCell cell = buildCell(fallback, true);
		return RecommendationCell.unavailable(cell.getLabel(), cell.getItemId());
	}

	private RecommendationCell buildCell(SlayerCodexDataStore.GearRow row, boolean includeOwnership)
	{
		List<Integer> candidateIds = itemResolver.resolveItemIds(row.getItemName(), row.getAltName());
		int itemId = candidateIds.isEmpty() ? itemResolver.resolveDisplayItemId(row.getItemName(), row.getAltName()) : candidateIds.get(0);
		String label = buildLabel(row);

		if (!includeOwnership)
		{
			return RecommendationCell.available(label, itemId, false, false, false);
		}

		Optional<Integer> ownedMatch = candidateIds.stream()
			.filter(id -> ownershipTracker.getOwnedQuantity(id) > 0)
			.findFirst();

		if (ownedMatch.isPresent())
		{
			int matchedId = ownedMatch.get();
			return RecommendationCell.available(
				label,
				matchedId,
				true,
				ownershipTracker.isEquipped(matchedId),
				ownershipTracker.isInBank(matchedId));
		}

		return RecommendationCell.available(label, itemId, false, false, false);
	}

	private String buildLabel(SlayerCodexDataStore.GearRow row)
	{
		if (row.getAltName() == null || row.getAltName().trim().isEmpty())
		{
			return row.getItemName();
		}
		return row.getItemName() + " (" + row.getAltName() + ")";
	}

	private static Map<String, Integer> buildSlotOrder()
	{
		List<String> order = List.of("HEAD", "NECK", "CAPE", "BODY", "LEGS", "WEAPON", "SHIELD", "AMMO", "HANDS", "FEET", "RING", "SPECIAL");
		Map<String, Integer> lookup = new LinkedHashMap<>();
		for (int i = 0; i < order.size(); i++)
		{
			lookup.put(order.get(i), i);
		}
		return Collections.unmodifiableMap(lookup);
	}

	private int compareSlot(String left, String right)
	{
		int leftIdx = SLOT_ORDER.getOrDefault(left, -1);
		int rightIdx = SLOT_ORDER.getOrDefault(right, -1);
		if (leftIdx == -1 && rightIdx == -1)
		{
			return left.compareTo(right);
		}
		if (leftIdx == -1)
		{
			return 1;
		}
		if (rightIdx == -1)
		{
			return -1;
		}
		return Integer.compare(leftIdx, rightIdx);
	}

	public static final class RecommendationRow
	{
		private final String slot;
		private final RecommendationCell wiki;
		private final RecommendationCell yourBest;
		private final List<String> noteIds;

		private RecommendationRow(
			String slot,
			RecommendationCell wiki,
			RecommendationCell yourBest,
			List<String> noteIds)
		{
			this.slot = slot;
			this.wiki = wiki;
			this.yourBest = yourBest;
			this.noteIds = noteIds;
		}

		public String getSlot()
		{
			return slot;
		}

		public RecommendationCell getWiki()
		{
			return wiki;
		}

		public RecommendationCell getYourBest()
		{
			return yourBest;
		}

		public List<String> getNoteIds()
		{
			return noteIds;
		}
	}

	public static final class RecommendationCell
	{
		private final String label;
		private final int itemId;
		private final boolean owned;
		private final boolean equipped;
		private final boolean banked;
		private final boolean unavailableFallback;

		private RecommendationCell(String label, int itemId, boolean owned, boolean equipped, boolean banked, boolean unavailableFallback)
		{
			this.label = label;
			this.itemId = itemId;
			this.owned = owned;
			this.equipped = equipped;
			this.banked = banked;
			this.unavailableFallback = unavailableFallback;
		}

		public static RecommendationCell available(String label, int itemId, boolean owned, boolean equipped, boolean banked)
		{
			return new RecommendationCell(label, itemId, owned, equipped, banked, false);
		}

		public static RecommendationCell unavailable(String label, int itemId)
		{
			return new RecommendationCell(label, itemId, false, false, false, true);
		}

		public static RecommendationCell placeholder(String label)
		{
			return new RecommendationCell(label, -1, false, false, false, false);
		}

		public String getLabel()
		{
			return label;
		}

		public int getItemId()
		{
			return itemId;
		}

		public boolean isOwned()
		{
			return owned;
		}

		public boolean isEquipped()
		{
			return equipped;
		}

		public boolean isBanked()
		{
			return banked;
		}

		public boolean isUnavailableFallback()
		{
			return unavailableFallback;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private static final class SlotAccumulator
	{
		private final Map<Integer, SlayerCodexDataStore.GearRow> rowsByTier = new LinkedHashMap<>();

		private List<String> collectNotes()
		{
			TreeSet<String> noteIds = new TreeSet<>();
			for (SlayerCodexDataStore.GearRow row : rowsByTier.values())
			{
				noteIds.addAll(row.getNoteIds());
			}
			return new ArrayList<>(noteIds);
		}
	}
}

package com.slayercodex;

import java.util.Collections;
import java.util.Set;
import javax.inject.Singleton;

/**
 * Shared singleton snapshot of the currently focused monster's recommended items,
 * read by the bank filter and item overlay. The plugin pushes updates whenever the
 * panel's selection or auto-detected task changes.
 */
@Singleton
public class SlayerCodexTaskState
{
	private volatile String monsterKey;
	private volatile String monsterName;
	private volatile Set<Integer> relevantItemIds = Collections.emptySet();

	public synchronized void update(String monsterKey, String monsterName, Set<Integer> relevantItemIds)
	{
		this.monsterKey = monsterKey;
		this.monsterName = monsterName;
		this.relevantItemIds = relevantItemIds == null ? Collections.emptySet() : relevantItemIds;
	}

	public synchronized void clear()
	{
		this.monsterKey = null;
		this.monsterName = null;
		this.relevantItemIds = Collections.emptySet();
	}

	public String getMonsterName()
	{
		return monsterName;
	}

	public Set<Integer> getRelevantItemIds()
	{
		return relevantItemIds;
	}

	public boolean hasFocus()
	{
		return monsterKey != null;
	}

	public boolean isRelevant(int itemId)
	{
		return itemId > 0 && relevantItemIds.contains(itemId);
	}
}

package com.slayercodex;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class SlayerCodexDataStoreTest
{
	@Test
	public void loadSupportsBuildBasedSchema() throws IOException
	{
		SlayerCodexDataStore store = new SlayerCodexDataStore();
		store.load();

		Assert.assertTrue("Expected monsters to be loaded", store.getMonsterCount() > 0);

		SlayerCodexDataStore.MonsterDetails hydra = store.getMonsterDetails("alchemical_hydra");
		Assert.assertNotNull("Expected alchemical_hydra details", hydra);
		Assert.assertFalse("Expected combat styles from builds", hydra.getCombatStyles().isEmpty());
	}

	@Test
	public void buildNotesAndSlotNotesResolveToFootnotes() throws IOException
	{
		SlayerCodexDataStore store = new SlayerCodexDataStore();
		store.load();

		SlayerCodexDataStore.MonsterDetails kbd = store.getMonsterDetails("king_black_dragon");
		Assert.assertNotNull("Expected king_black_dragon details", kbd);
		Assert.assertFalse("Expected at least one style", kbd.getCombatStyles().isEmpty());

		SlayerCodexDataStore.CombatStyleDetails firstStyle = kbd.getCombatStyles().get(0);
		Assert.assertFalse("Expected build-level notes for style", firstStyle.getBuildNoteIds().isEmpty());

		List<SlayerCodexDataStore.GearRow> rows = new ArrayList<>();
		for (List<SlayerCodexDataStore.GearRow> tierRows : firstStyle.getTierRows().values())
		{
			rows.addAll(tierRows);
		}

		Assert.assertFalse("Expected gear rows for style", rows.isEmpty());

		List<String> noteIds = new ArrayList<>();
		for (SlayerCodexDataStore.GearRow row : rows)
		{
			noteIds.addAll(row.getNoteIds());
		}

		Assert.assertFalse("Expected item/slot note references", noteIds.isEmpty());

		for (String noteId : noteIds)
		{
			Assert.assertTrue(
				"Missing resolved note text for note id: " + noteId,
				kbd.getFootnotes().containsKey(noteId));
		}
	}

	@Test
	public void allMonstersAndStylesParseWithoutBrokenReferences() throws IOException
	{
		SlayerCodexDataStore store = new SlayerCodexDataStore();
		store.load();

		List<String> failures = new ArrayList<>();
		for (SlayerCodexDataStore.MonsterSummary summary : store.getMonsterSummaries())
		{
			SlayerCodexDataStore.MonsterDetails details = store.getMonsterDetails(summary.getKey());
			if (details == null)
			{
				failures.add(summary.getKey() + ": missing details");
				continue;
			}

			if (details.getCombatStyles().isEmpty())
			{
				failures.add(summary.getKey() + ": no combat styles");
				continue;
			}

			for (SlayerCodexDataStore.CombatStyleDetails style : details.getCombatStyles())
			{
				if (style.getName() == null || style.getName().trim().isEmpty())
				{
					failures.add(summary.getKey() + ": blank style name");
					continue;
				}

				for (String buildNoteId : style.getBuildNoteIds())
				{
					if (!details.getFootnotes().containsKey(buildNoteId))
					{
						failures.add(summary.getKey() + " / " + style.getName() + ": missing build note " + buildNoteId);
					}
				}

				for (Map.Entry<Integer, List<SlayerCodexDataStore.GearRow>> tierEntry : style.getTierRows().entrySet())
				{
					for (SlayerCodexDataStore.GearRow row : tierEntry.getValue())
					{
						if (row.getSlot() == null || row.getSlot().trim().isEmpty())
						{
							failures.add(summary.getKey() + " / " + style.getName() + ": row with blank slot");
						}

						if (row.getItemName() == null || row.getItemName().trim().isEmpty())
						{
							failures.add(summary.getKey() + " / " + style.getName() + ": row with blank item name");
						}

						for (String noteId : row.getNoteIds())
						{
							if (!details.getFootnotes().containsKey(noteId))
							{
								failures.add(summary.getKey() + " / " + style.getName() + ": missing item note " + noteId);
							}
						}
					}
				}
			}
		}

		Assert.assertTrue("Dataset QA failures:\n" + String.join("\n", failures), failures.isEmpty());
	}
}

